    public async Task<List<LeasingNotification>> LeasingNotificationHistoryAsync(Guid account,CancellationToken ct=default){await using var db=await factory.CreateDbContextAsync(ct);var(_,admin)=await Member(db,account,ct);if(!admin)throw new UnauthorizedAccessException();return await db.LeasingNotifications.AsNoTracking().Where(x=>x.AccountId==account).OrderByDescending(x=>x.ScheduledUtc).Take(200).ToListAsync(ct);}
