    public async Task<LeasingFollowupPage> ListLeasingFollowupsAsync(Guid account,LeasingFollowupKind? kind=null,LeasingFollowupStatus? status=null,DateOnly? to=null,Guid? owner=null,int page=1,CancellationToken ct=default)
    {
        await using var db=await factory.CreateDbContextAsync(ct);var(user,admin)=await Member(db,account,ct);var elevated=await LifecycleReader(admin,ct);var acquisitions=Acquisitions(db,account,user,elevated).Select(x=>x.Id);var frameworks=Frameworks(db,account,user,elevated).Select(x=>x.Id);
        await new LeasingLifecycleProcessor(factory,clock).RunAccountAsync(account,ct);
        var query=db.LeasingFollowups.AsNoTracking().Where(x=>x.AccountId==account&&(x.AcquisitionId.HasValue&&acquisitions.Contains(x.AcquisitionId.Value)||x.FrameworkId.HasValue&&frameworks.Contains(x.FrameworkId.Value)));
        if(kind.HasValue)query=query.Where(x=>x.Kind==kind);if(status.HasValue)query=query.Where(x=>x.Status==status);else query=query.Where(x=>x.Status!=LeasingFollowupStatus.Obsolete);if(to.HasValue)query=query.Where(x=>x.DueDate==null||x.DueDate<=to);if(owner.HasValue)query=query.Where(x=>x.OwnerUserId==owner);
        var count=await query.CountAsync(ct);page=Math.Clamp(page,1,Math.Max(1,(count+49)/50));var rows=await query.OrderBy(x=>x.DueDate).ThenBy(x=>x.Id).Skip((page-1)*50).Take(50).ToListAsync(ct);
        var names=await Acquisitions(db,account,user,elevated).AsNoTracking().ToDictionaryAsync(x=>x.Id,x=>x.Name,ct);foreach(var f in await Frameworks(db,account,user,elevated).AsNoTracking().ToListAsync(ct))names[f.Id]=f.Name;
        var visibleTasks=db.LeasingFollowups.Where(x=>x.AccountId==account&&(x.AcquisitionId.HasValue&&acquisitions.Contains(x.AcquisitionId.Value)||x.FrameworkId.HasValue&&frameworks.Contains(x.FrameworkId.Value))).Select(x=>x.Id);
        var notes=await db.LeasingNotifications.AsNoTracking().Where(x=>x.AccountId==account&&x.RecipientUserId==user&&x.Status==LeasingNotificationStatus.Delivered&&visibleTasks.Contains(x.FollowupId)).OrderByDescending(x=>x.DeliveredUtc).Take(100).ToListAsync(ct);
        var noteIds=notes.Select(x=>x.FollowupId).ToArray();return new(rows,count,page,names,notes,await db.LeasingFollowups.AsNoTracking().Where(x=>x.AccountId==account&&noteIds.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,ct));
    }
