        var canManage=admin||await authorization.CanManageLeasingLifecycleAsync(ct)||(task.AcquisitionId.HasValue?await Acquisitions(db,account,user,false).AnyAsync(x=>x.Id==task.AcquisitionId,ct):await Frameworks(db,account,user,false).AnyAsync(x=>x.Id==task.FrameworkId,ct));if(!canManage)throw new UnauthorizedAccessException();
        if(await PaymentRetry(db,account,request,user,"LifecycleTask",task.AcquisitionId,null,ct))return;CheckRevision(task.Revision,revision,true);Reason(comment,true);if(status is not(LeasingFollowupStatus.Open or LeasingFollowupStatus.InProgress or LeasingFollowupStatus.Completed)||task.Status==LeasingFollowupStatus.Obsolete)throw new LeasingValidationException("LeasingInvalidTransition");if(owner.HasValue&&!await LeasingLifecycleAccess.CanRead(db,account,owner.Value,task.AcquisitionId,task.FrameworkId,ct))throw new LeasingValidationException("LifeInvalidOwner");
        var before=Snapshot(task);task.OwnerUserId=owner;task.AssignedExplicitly=true;task.Status=status;task.Comment=comment;task.CompletedByUserId=status==LeasingFollowupStatus.Completed?user:null;task.CompletedUtc=status==LeasingFollowupStatus.Completed?clock.GetUtcNow():null;task.Revision=Guid.NewGuid();PaymentEvent(db,account,task.AcquisitionId,null,user,"LifecycleTask",comment,before,Snapshot(task),request);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);
    }
    public async Task ReadLeasingNotificationAsync(Guid account,Guid id,CancellationToken ct=default){await using var db=await factory.CreateDbContextAsync(ct);var(user,_)=await Member(db,account,ct);var n=await db.LeasingNotifications.SingleOrDefaultAsync(x=>x.AccountId==account&&x.Id==id&&x.RecipientUserId==user,ct)??throw new UnauthorizedAccessException();var task=await db.LeasingFollowups.SingleAsync(x=>x.AccountId==account&&x.Id==n.FollowupId,ct);if(!await LeasingLifecycleAccess.CanRead(db,account,user,task.AcquisitionId,task.FrameworkId,ct))throw new UnauthorizedAccessException();n.ReadUtc??=clock.GetUtcNow();await db.SaveChangesAsync(ct);}
